    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "The shuffle chain map and Moore normalization", H("The shuffle chain map and Moore normalization"), Blocks(
        Paragraph(Text("Fix an abelian category C : Type u with Category.{v} C and independent universes u,v. Every X is an arbitrary bisimplicial object in C. The complexes FOne and FTwo are the total double alternating-face complex and the diagonal alternating-face complex, respectively, in ChainComplex C ℕ.")),
        Paragraph(Text("The two coordinate maps of a (p,q)-shuffle give simplex maps [p+q] → [p] and [p+q] → [q]. Contravariance realizes their pair as X[p,q] → X[p+q,p+q]. The sum of these maps with integer shuffle signs is ezComponent. Its boundary splits into first-coordinate and second-coordinate insertion terms; the marked diagonal vertices cancel by the sign-reversing involution. Total descent packages the resulting shuffleMap : FOne(X) → FTwo(X).")),
        Paragraph(Text("NOne is the total complex after Moore normalization in both directions, and NTwo is the normalized Moore complex of the diagonal. Each uses the pinned Dold–Kan inclusion and retraction. The normalized shuffle and Alexander–Whitney maps are obtained by inclusion, the corresponding unnormalized map, and retraction. The Moore convention is the intersection of the positive-face kernels, rather than the quotient-by-degeneracies convention of the original product-chain formulation.")),
        Describe.Lean(DescribeId.Create("ez-bisimplicial-shufflefsthom-c4186b"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/Bisimplicial.shuffleFstHom"), H("shuffleFstHom"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("First projection of a shuffle as a `SimplexCategory` morphism `⦋p+q⦌ ⟶ ⦋p⦌`.")), Paragraph(Text("In this notation, def shuffleFstHom {p q : ℕ} (μ : Shuffle p q) : (⦋p + q⦌ : SimplexCategory) ⟶ ⦋p⦌."))), DescribeRole.Definition),
        Describe.Lean(DescribeId.Create("ez-bisimplicial-shufflesndhom-c627a3"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/Bisimplicial.shuffleSndHom"), H("shuffleSndHom"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("Second projection of a shuffle as a `SimplexCategory` morphism `⦋p+q⦌ ⟶ ⦋q⦌`.")), Paragraph(Text("In this notation, def shuffleSndHom {p q : ℕ} (μ : Shuffle p q) : (⦋p + q⦌ : SimplexCategory) ⟶ ⦋q⦌."))), DescribeRole.Definition),
        Describe.Lean(DescribeId.Create("ez-bisimplicial-ezcomponent-d2a372"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/Bisimplicial.ezComponent"), H("ezComponent"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("The `(p, q)` component of the shuffle map.")), Paragraph(Text("In this notation, noncomputable def ezComponent (X : BisimplicialObject C) (p q : ℕ) : (X.obj (Opposite.op ⦋p⦌)).obj (Opposite.op ⦋q⦌) ⟶ (X.obj (Opposite.op ⦋p + q⦌)).obj (Opposite.op ⦋p + q⦌)."))), DescribeRole.Definition),
        Describe.Lean(DescribeId.Create("ez-bisimplicial-fsthom-insertleftstep-comp-656154"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/Bisimplicial.fstHom_insertLeftStep_comp_δ"), H("fstHom_insertLeftStep_comp_δ"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("Left insertion face factorization (fst component): `δ_{insertLeftIndex} ≫ eqToHom ≫ fstHom(insertLeftStep ν j) = fstHom(ν) ≫ δ(j)`.")), Paragraph(Text("In this notation, lemma fstHom_insertLeftStep_comp_δ {p q n : ℕ} (ν : Shuffle p q) (j : Fin (p + 2)) (hn : n + 1 = (p + 1) + q) : SimplexCategory.δ ((ν.insertLeftIndex j).cast (by omega)) ≫ eqToHom (congrArg SimplexCategory.mk hn) ≫ shuffleFstHom (ν.insertLeftStep j) = eqToHom (congrArg SimplexCategory.mk (by omega : n = p + q)) ≫ shuffleFstHom ν ≫ SimplexCategory.δ j."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-bisimplicial-sndhom-insertrightstep-comp-ebbfe2"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/Bisimplicial.sndHom_insertRightStep_comp_δ"), H("sndHom_insertRightStep_comp_δ"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("Right insertion face factorization (snd component): `δ_{insertRightIndex} ≫ eqToHom ≫ sndHom(insertRightStep ν k) = sndHom(ν) ≫ δ(k)`.")), Paragraph(Text("In this notation, lemma sndHom_insertRightStep_comp_δ {p q n : ℕ} (ν : Shuffle p q) (k : Fin (q + 2)) (hn : n + 1 = p + (q + 1)) : SimplexCategory.δ ((ν.insertRightIndex k).cast (by omega)) ≫ eqToHom (congrArg SimplexCategory.mk hn) ≫ shuffleSndHom (ν.insertRightStep k) = eqToHom (congrArg SimplexCategory.mk (by omega : n = p + q)) ≫ shuffleSndHom ν ≫ SimplexCategory.δ k."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-bisimplicial-fsthom-swapdiagonalsteps-comp-81960b"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/Bisimplicial.fstHom_swapDiagonalSteps_comp_δ"), H("fstHom_swapDiagonalSteps_comp_δ"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("Composing `δ r ≫ eqToHom ≫ shuffleFstHom` of `swapDiagonalSteps μ` gives the same result as for `μ`, because `δ r` maps via `succAbove r` which avoids vertex `r`, and `swapDiagonalSteps` only changes the value at `r`.")), Paragraph(Text("In this notation, lemma fstHom_swapDiagonalSteps_comp_δ {p q n : ℕ} (μ : Shuffle p q) (r : Fin (n + 2)) (hn : n + 1 = p + q) (h : Shuffle.isDiagonalVertex μ (r.cast (by omega))) : SimplexCategory.δ r ≫ eqToHom (congrArg SimplexCategory.mk hn) ≫ shuffleFstHom (μ.swapDiagonalSteps (r.cast (by omega)) h) = SimplexCategory.δ r ≫ eqToHom (congrArg SimplexCategory.mk hn) ≫ shuffleFstHom μ."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-bisimplicial-sndhom-swapdiagonalsteps-comp-227edd"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/Bisimplicial.sndHom_swapDiagonalSteps_comp_δ"), H("sndHom_swapDiagonalSteps_comp_δ"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("Deleting the marked diagonal vertex makes the second-coordinate simplex maps agree before and after the corner swap.")), Paragraph(Text("In this notation, lemma sndHom_swapDiagonalSteps_comp_δ {p q n : ℕ} (μ : Shuffle p q) (r : Fin (n + 2)) (hn : n + 1 = p + q) (h : Shuffle.isDiagonalVertex μ (r.cast (by omega))) : SimplexCategory.δ r ≫ eqToHom (congrArg SimplexCategory.mk hn) ≫ shuffleSndHom (μ.swapDiagonalSteps (r.cast (by omega)) h) = SimplexCategory.δ r ≫ eqToHom (congrArg SimplexCategory.mk hn) ≫ shuffleSndHom μ."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-bisimplicial-ezcomponent-boundary-afa7c9"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/Bisimplicial.ezComponent_boundary"), H("ezComponent_boundary"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("Boundary formula for `ezComponent`. Composing `ezComponent X p q` with the diagonal differential splits into the vertical boundary term coming from the first simplicial direction and the horizontal boundary term coming from the second. The differential is written as `.d` rather than `objD` to avoid index-cast noise.")), Paragraph(Text("In this notation, lemma ezComponent_boundary (X : BisimplicialObject C) (p q j : ℕ) (h : (ComplexShape.down ℕ).Rel (p + q) j) : ezComponent X p q ≫ @eqToHom _ _ ((X.obj (Opposite.op ⦋p + q⦌)).obj (Opposite.op ⦋p + q⦌)) (((alternatingFaceMapComplex C).obj (diag.obj X)).X (p + q)) rfl ≫ ((alternatingFaceMapComplex C).obj (diag.obj X)).d (p + q) j = (match p with | 0 => 0 | p' + 1 => ∑ k : Fin (p' + 2), (-1 : ℤ) ^ (k : ℕ) • ((X.map (SimplexCategory.δ k).op).app (Opposite.op ⦋q⦌) ≫ ezComponent X p' q ≫ eqToHom (by have : j + 1 = p' + 1 + q := by rwa [ComplexShape.down_Rel] at h simp [show p' + q = j from by omega]))) + (match q with | 0 => 0 | q' + 1 => (-1 : ℤ) ^ p • ∑ k : Fin (q' + 2), (-1 : ℤ) ^ (k : ℕ) • ((X.obj (Opposite.op ⦋p⦌)).map (SimplexCategory.δ k).op ≫ ezComponent X p q' ≫ eqToHom (by have : j + 1 = p + (q' + 1) := by rwa [ComplexShape.down_Rel] at h simp [show p + q' = j from by omega])))."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-bisimplicial-shufflemap-53a2d3"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/Bisimplicial.shuffleMap"), H("shuffleMap"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("The shuffle chain map `FOne(X) ⟶ FTwo(X)`.")), Paragraph(Text("In this notation, noncomputable def shuffleMap (X : BisimplicialObject C) : FOne.obj X ⟶ FTwo.obj X."))), DescribeRole.Definition),
        Describe.Lean(DescribeId.Create("ez-bisimplicial-alexanderwhitney-comp-shufflemap-f-2c1e2c"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/Bisimplicial.alexanderWhitney_comp_shuffleMap_f"), H("alexanderWhitney_comp_shuffleMap_f"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("Degreewise formula for `alexanderWhitney ≫ shuffleMap`.")), Paragraph(Text("In this notation, lemma alexanderWhitney_comp_shuffleMap_f (X : BisimplicialObject C) (q : ℕ) : (alexanderWhitney X ≫ shuffleMap X).f q = ∑ p : Fin (q + 1), eqToHom (by simp [Nat.add_sub_cancel' (Nat.lt_succ_iff.mp p.isLt)]) ≫ awComponent X p (q - p) ≫ ezComponent X p (q - p) ≫ eqToHom (by simp [Nat.add_sub_cancel' (Nat.lt_succ_iff.mp p.isLt)])."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-bisimplicial-awshuffle-f-zero-0a2b82"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/Bisimplicial.awShuffle_f_zero"), H("awShuffle_f_zero"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("In degree `0`, the composite `alexanderWhitney ≫ shuffleMap` is the identity.")), Paragraph(Text("In this notation, lemma awShuffle_f_zero (X : BisimplicialObject C) : (alexanderWhitney X ≫ shuffleMap X).f 0 = (𝟙 (FTwo.obj X) : (FTwo.obj X) ⟶ (FTwo.obj X)).f 0."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-bisimplicial-6504607dbcfd"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/Bisimplicial.NOne"), H("NOne"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("The **bi-normalized total complex**: normalize both simplicial directions (via the normalized Moore complex), then take the total complex. The normalized analogue of `FOne`.")), Paragraph(Text("In this notation, noncomputable abbrev NOne : BisimplicialObject C ⥤ ChainComplex C ℕ."))), DescribeRole.Definition),
